// Shape of the page copy. en.ts and hr.ts both `satisfies Copy`, so TypeScript reports a
// key that one language has and the other lacks. Any text that contains a number is a
// function of `facts` (site/src/data/facts.json, generated by scripts/site-facts.ts),
// never a literal. Backticks in a text mark inline code (rendered by Prose.astro).
import type factsJson from '../../data/facts.json';

export type Facts = typeof factsJson;
export type Level = Facts['levels'][number];
export type Text = string | ((f: Facts) => string);

// Levels are keyed by their first fixture, because `levels[].id` is not unique
// (two L4 rows). HR scopes are written per key; EN takes `levels[].scope` from facts.json.
export const levelKeys = [
  'l0', 'l1', 'l3', 'records', 'access', 'l5', 'l6', 'routes', 'events', 'l7', 'l9',
] as const;
export type LevelKey = (typeof levelKeys)[number];
export const levelKey = (l: Level) => l.fixtures[0].name as LevelKey;

// Commands are code and are not translated; only their comments are.
export type CommandId = 'install' | 'check' | 'level' | 'db' | 'cli' | 'start';
export type EnvVar =
  | 'DATABASE_URL'
  | 'PORT'
  | 'PUBLIC_URL'
  | 'OPEN_LEDGER_MASTER_KEY'
  | 'OPEN_LEDGER_DELIVERY_MAX_RETRIES'
  | 'OPEN_LEDGER_LOG';

export type Copy = {
  /** Section 12: <title> and <meta name="description">. */
  meta: { title: Text; description: Text };
  /** Section 1. */
  hero: {
    lead: Text[];
    buttons: { github: string; run: string; proof: string };
  };
  /** Section 2: one label per number; `value` is rendered large, `label` beside it. */
  numbers: {
    intro: Text;
    items: { value: Text; label: Text }[];
  };
  /** Section 3. `diagram` are the box labels for the W5 SVG. */
  proof: {
    intro: Text;
    steps: Text[];
    placeholders: Text;
    bridges: Text;
    divergences: Text;
    example: Text;
    precedence: Text;
    diagram: {
      sdk: string;
      proxy: string;
      sandbox: string;
      ours: string;
      reference: string;
      candidate: string;
      compare: string;
      exceptions: string;
      /** figcaption and aria-label: what the diagram shows, numbers refer to `steps`. */
      caption: string;
    };
  };
  /** Section 4. */
  levels: {
    intro: Text;
    columns: { level: string; scope: string; client: string; bridge: string; differ: string; fixtures: string };
    scope: (l: Level) => string;
    notes: Text[];
  };
  /** Section 5. */
  interop: { paragraphs: Text[]; docsLink: string };
  /** Section 6: teaser on the home page and the intro of /coverage. */
  coverage: { teaser: Text; link: string; pageIntro: Text[] };
  /** Section 7. */
  running: {
    requirements: Text;
    commandsIntro: Text;
    commands: Record<CommandId, Text>;
    envIntro: Text;
    env: Record<EnvVar, Text>;
    clients: Text;
    record: Text;
    copy: string;
    copied: string;
  };
  /** Section 8. */
  design: {
    stores: Text;
    serialisation: Text;
    invariantsIntro: Text;
    invariants: Text[];
    lineCoverage: Text;
    gapsTitle: string;
    gaps: Text[];
    backlog: Text;
  };
  /** Section 9. */
  nonGoals: { paragraphs: Text[] };
  /** Section 10: teaser on the home page and the intro of /findings. */
  findings: { teaser: Text[]; link: string; pageIntro: Text[]; languageNote: string };
};

export const text = (t: Text, f: Facts): string => (typeof t === 'function' ? t(f) : t);
